import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"在 MiniTavern 中配置生图","description":"设置 → 生图 → 生图连接：对接本机 A1111 / ComfyUI 或云端生图 API。","frontmatter":{"title":"在 MiniTavern 中配置生图","description":"设置 → 生图 → 生图连接：对接本机 A1111 / ComfyUI 或云端生图 API。","head":[["meta",{"property":"og:title","content":"在 MiniTavern 中配置生图 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"设置 → 生图 → 生图连接：对接本机 A1111 / ComfyUI 或云端生图 API。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"local/image-gen/connect-app.md","filePath":"local/image-gen/connect-app.md","lastUpdated":1786517442000}'),o={name:"local/image-gen/connect-app.md"};function n(i,t,l,c,h,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="在-minitavern-中配置生图" tabindex="-1">在 MiniTavern 中配置生图 <a class="header-anchor" href="#在-minitavern-中配置生图" aria-label="Permalink to &quot;在 MiniTavern 中配置生图&quot;">​</a></h1><p>本文对应 App 路径：<strong>设置 → 生图 → 生图连接</strong>。</p><p>生图参数、智能生图、关键词触发见 <a href="/ultra_guides/manual/model-link#生图连接--智能--关键词">模型连接 · 生图</a>。</p><h2 id="新建生图连接" tabindex="-1">新建生图连接 <a class="header-anchor" href="#新建生图连接" aria-label="Permalink to &quot;新建生图连接&quot;">​</a></h2><ol><li>打开 MiniTavern → 底部 <strong>设置</strong>。</li><li>进入 <strong>生图</strong> → <strong>生图连接</strong>。</li><li>点 <strong>新建</strong>。</li><li>选择 <strong>平台</strong>，填写 Base URL / API Key / 模型（按平台不同）。</li><li><strong>测连</strong> 成功后保存，并设为默认（若列表支持）。</li></ol><h2 id="本机-a1111" tabindex="-1">本机 A1111 <a class="header-anchor" href="#本机-a1111" aria-label="Permalink to &quot;本机 A1111&quot;">​</a></h2><p>先完成 <a href="./a1111">A1111 安装并开启 <code>--api --listen</code></a>。</p><table tabindex="0"><thead><tr><th>项</th><th>填写示例</th></tr></thead><tbody><tr><td>平台</td><td><strong>A1111(SD WebUI)</strong>（或自定义 A1111 协议）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>一般可空；若 WebUI 开了 <code>--api-auth</code> 再按提示填</td></tr><tr><td>模型</td><td>可空或选 WebUI 中的 checkpoint 名（以 App 列表为准）</td></tr></tbody></table><p>将 <code>YOUR_PC_IP</code> 换成电脑局域网 IP。<br><strong>不要</strong>填 <code>http://127.0.0.1:7860</code>（那是电脑自己，不是手机）。</p><h2 id="本机-comfyui" tabindex="-1">本机 ComfyUI <a class="header-anchor" href="#本机-comfyui" aria-label="Permalink to &quot;本机 ComfyUI&quot;">​</a></h2><p>先完成 <a href="./comfyui">ComfyUI 安装并 <code>--listen</code></a>。</p><table tabindex="0"><thead><tr><th>项</th><th>填写示例</th></tr></thead><tbody><tr><td>平台</td><td><strong>ComfyUI</strong>（或自定义 ComfyUI 协议）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code>（Desktop 常见 <code>:8000</code>）</td></tr><tr><td>API Key</td><td>一般可空</td></tr><tr><td>模型 / checkpoint</td><td>以 App 拉取到的列表为准；需机器上已有对应文件</td></tr></tbody></table><p>测连失败时：用手机浏览器先打开同一 Base URL，确认不是防火墙或未 listen。</p><h2 id="云端生图-可选" tabindex="-1">云端生图（可选） <a class="header-anchor" href="#云端生图-可选" aria-label="Permalink to &quot;云端生图（可选）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>何时用</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>官方 Images API（通常付费）</td></tr><tr><td>Gemini(Google)</td><td>Gemini 图像模型（多数需付费档，以 Google 定价为准）</td></tr><tr><td>OpenRouter</td><td>路由到支持图像的上游</td></tr><tr><td>Qwen</td><td>通义万相 / Qwen-Image（看百炼是否有免费额度）</td></tr><tr><td>自定义 (OpenAI Images)</td><td>硅基流动等兼容 <code>/images/generations</code> 的网关</td></tr></tbody></table><p>免费云端与 Key 获取见 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a>。</p><h2 id="在聊天里生图" tabindex="-1">在聊天里生图 <a class="header-anchor" href="#在聊天里生图" aria-label="Permalink to &quot;在聊天里生图&quot;">​</a></h2><p>配置默认生图连接后：</p><table tabindex="0"><thead><tr><th>入口</th><th>说明</th></tr></thead><tbody><tr><td>输入 <code>/imagine 提示词</code></td><td>自由生图（会经主聊天模型转写视觉 prompt）</td></tr><tr><td>附件 → 生图</td><td>根据故事 / 最后消息 / 背景 / 自由</td></tr><tr><td>长按气泡 → 生图</td><td>针对该气泡上下文</td></tr></tbody></table><p>主聊天模型也需已配置（转写 prompt 用）。仅配生图、未配聊天模型时，部分模式会失败。</p><h2 id="排错速查" tabindex="-1">排错速查 <a class="header-anchor" href="#排错速查" aria-label="Permalink to &quot;排错速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>排查</th></tr></thead><tbody><tr><td>测连失败 / 超时</td><td>电脑服务是否在跑；是否 <code>--api</code> / <code>--listen</code>；IP 与端口是否对；同一 Wi‑Fi</td></tr><tr><td>本机浏览器可以、手机不行</td><td>防火墙；访客网络隔离；填了 <code>127.0.0.1</code></td></tr><tr><td>A1111 404</td><td>未加 <code>--api</code>；Base URL 多写了路径</td></tr><tr><td>Comfy 一直转圈</td><td>看电脑端 Comfy 队列与报错；显存不足；无可用 checkpoint</td></tr><tr><td>有参考图但脸不对（Comfy）</td><td>当前默认 workflow 不消费参考图 → 换 A1111 或云端</td></tr></tbody></table><p>更完整的聊天错误码见 <a href="/ultra_guides/manual/errors">错误排错</a>。</p>',23)])])}const g=e(o,[["render",n]]);export{m as __pageData,g as default};
